61: /**
62:  * \brief           Initialize buffer handle to default values with size and buffer data array
63:  * \param[in]       buff: Ring buffer instance
64:  * \param[in]       buffdata: Pointer to memory to use as buffer data
65:  * \param[in]       size: Size of `buffdata` in units of bytes
66:  *                      Maximum number of bytes buffer can hold is `size - 1`
67:  * \return          `1` on success, `0` otherwise
68:  */
69: uint8_t
70: lwrb_init(lwrb_t* buff, void* buffdata, lwrb_sz_t size) {
71:     if (buff == NULL || buffdata == NULL || size == 0) {
72:         return 0;
73:     }
74: 
75:     buff->evt_fn = NULL;
76:     buff->size = size;
77:     buff->buff = buffdata;
78:     LWRB_INIT(buff->w_ptr, 0);
79:     LWRB_INIT(buff->r_ptr, 0);
80:     return 1;
81: }
82: 
83: /**
84:  * \brief           Check if buff is initialized and ready to use
85:  * \param[in]       buff: Ring buffer instance
86:  * \return          `1` if ready, `0` otherwise
87:  */
88: uint8_t
89: lwrb_is_ready(lwrb_t* buff) {
90:     return BUF_IS_VALID(buff);
91: }
92: 
93: /**
94:  * \brief           Free buffer memory
95:  * \note            Since implementation does not use dynamic allocation,
96:  *                  it just sets buffer handle to `NULL`
97:  * \param[in]       buff: Ring buffer instance
98:  */
99: void
100: lwrb_free(lwrb_t* buff) {
101:     if (BUF_IS_VALID(buff)) {
102:         buff->buff = NULL;
103:     }
104: }
105: 
106: /**
107:  * \brief           Set event function callback for different buffer operations
108:  * \param[in]       buff: Ring buffer instance
109:  * \param[in]       evt_fn: Callback function
110:  */
111: void
112: lwrb_set_evt_fn(lwrb_t* buff, lwrb_evt_fn evt_fn) {
113:     if (BUF_IS_VALID(buff)) {
114:         buff->evt_fn = evt_fn;
115:     }
116: }
117: 
118: /**
119:  * \brief           Set custom buffer argument, that can be retrieved in the event function
120:  * \param[in]       buff: Ring buffer instance
121:  * \param[in]       arg: Custom user argument
122:  */
123: void
124: lwrb_set_arg(lwrb_t* buff, void* arg) {
125:     if (BUF_IS_VALID(buff)) {
126:         buff->arg = arg;
127:     }
128: }
129: 
130: /**
131:  * \brief           Get custom buffer argument, previously set with \ref lwrb_set_arg
132:  * \param[in]       buff: Ring buffer instance
133:  * \return          User argument, previously set with \ref lwrb_set_arg
134:  */
135: void*
136: lwrb_get_arg(lwrb_t* buff) {
137:     return buff != NULL ? buff->arg : NULL;
138: }
139: 
140: /**
141:  * \brief           Write data to buffer.
142:  *                  Copies data from `data` array to buffer and advances the write pointer for a maximum of `btw` number of bytes.
143:  * 
144:  *                  It copies less if there is less memory available in the buffer.
145:  *                  User must check the return value of the function and compare it to
146:  *                  the requested write length, to determine if everything has been written
147:  * 
148:  * \note            Use \ref lwrb_write_ex for more advanced usage
149:  *
150:  * \param[in]       buff: Ring buffer instance
151:  * \param[in]       data: Pointer to data to write into buffer
152:  * \param[in]       btw: Number of bytes to write
153:  * \return          Number of bytes written to buffer.
154:  *                      When returned value is less than `btw`, there was no enough memory available
155:  *                      to copy full data array.
156:  */
157: lwrb_sz_t
158: lwrb_write(lwrb_t* buff, const void* data, lwrb_sz_t btw) {
159:     lwrb_sz_t written = 0;
160: 
161:     if (lwrb_write_ex(buff, data, btw, &written, 0)) {
162:         return written;
163:     }
164:     return 0;
165: }
166: 
167: /**
168:  * \brief           Write extended functionality
169:  * 
170:  * \param           buff: Ring buffer instance
171:  * \param           data: Pointer to data to write into buffer
172:  * \param           btw: Number of bytes to write
173:  * \param           bwritten: Output pointer to write number of bytes written into the buffer
174:  * \param           flags: Optional flags.
175:  *                      \ref LWRB_FLAG_WRITE_ALL: Request to write all data (up to btw).
176:  *                          Will early return if no memory available
177:  * \return          `1` if write operation OK, `0` otherwise
178:  */
179: uint8_t
180: lwrb_write_ex(lwrb_t* buff, const void* data, lwrb_sz_t btw, lwrb_sz_t* bwritten, uint16_t flags) {
181:     lwrb_sz_t tocopy = 0, free = 0, w_ptr = 0;
182:     const uint8_t* d_ptr = data;
183: 
184:     if (!BUF_IS_VALID(buff) || data == NULL || btw == 0) {
185:         return 0;
186:     }
187: 
188:     /* Calculate maximum number of bytes available to write */
189:     free = lwrb_get_free(buff);
190:     /* If no memory, or if user wants to write ALL data but no enough space, exit early */
191:     if (free == 0 || (free < btw && (flags & LWRB_FLAG_WRITE_ALL))) {
192:         return 0;
193:     }
194:     btw = BUF_MIN(free, btw);
195:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_acquire);
196: 
197:     /* Step 1: Write data to linear part of buffer */
198:     tocopy = BUF_MIN(buff->size - w_ptr, btw);
199:     BUF_MEMCPY(&buff->buff[w_ptr], d_ptr, tocopy);
200:     d_ptr += tocopy;
201:     w_ptr += tocopy;
202:     btw -= tocopy;
203: 
204:     /* Step 2: Write data to beginning of buffer (overflow part) */
205:     if (btw > 0) {
206:         BUF_MEMCPY(buff->buff, d_ptr, btw);
207:         w_ptr = btw;
208:     }
209: 
210:     /* Step 3: Check end of buffer */
211:     if (w_ptr >= buff->size) {
212:         w_ptr = 0;
213:     }
214: 
215:     /*
216:      * Write final value to the actual running variable.
217:      * This is to ensure no read operation can access intermediate data
218:      */
219:     LWRB_STORE(buff->w_ptr, w_ptr, memory_order_release);
220: 
221:     BUF_SEND_EVT(buff, LWRB_EVT_WRITE, tocopy + btw);
222:     if (bwritten != NULL) {
223:         *bwritten = tocopy + btw;
224:     }
225:     return 1;
226: }
227: 
228: /**
229:  * \brief           Read data from buffer.
230:  *                  Copies data from `data` array to buffer and advances the read pointer for a maximum of `btr` number of bytes.
231:  * 
232:  *                  It copies less if there is less data available in the buffer.
233:  * 
234:  * \note            Use \ref lwrb_read_ex for more advanced usage
235:  *
236:  * \param[in]       buff: Ring buffer instance
237:  * \param[out]      data: Pointer to output memory to copy buffer data to
238:  * \param[in]       btr: Number of bytes to read
239:  * \return          Number of bytes read and copied to data array
240:  */
241: lwrb_sz_t
242: lwrb_read(lwrb_t* buff, void* data, lwrb_sz_t btr) {
243:     lwrb_sz_t read = 0;
244: 
245:     if (lwrb_read_ex(buff, data, btr, &read, 0)) {
246:         return read;
247:     }
248:     return 0;
249: }
250: 
251: /**
252:  * \brief           Read extended functionality
253:  * 
254:  * \param           buff: Ring buffer instance
255:  * \param           data: Pointer to memory to write read data from buffer 
256:  * \param           btr: Number of bytes to read
257:  * \param           bread: Output pointer to write number of bytes read from buffer and written to the 
258:  *                      output `data` variable
259:  * \param           flags: Optional flags
260:  *                      \ref LWRB_FLAG_READ_ALL: Request to read all data (up to btr).
261:  *                          Will early return if no enough bytes in the buffer
262:  * \return          `1` if read operation OK, `0` otherwise
263:  */
264: uint8_t
265: lwrb_read_ex(lwrb_t* buff, void* data, lwrb_sz_t btr, lwrb_sz_t* bread, uint16_t flags) {
266:     lwrb_sz_t tocopy = 0, full = 0, r_ptr = 0;
267:     uint8_t* d_ptr = data;
268: 
269:     if (!BUF_IS_VALID(buff) || data == NULL || btr == 0) {
270:         return 0;
271:     }
272: 
273:     /* Calculate maximum number of bytes available to read */
274:     full = lwrb_get_full(buff);
275:     if (full == 0 || (full < btr && (flags & LWRB_FLAG_READ_ALL))) {
276:         return 0;
277:     }
278:     btr = BUF_MIN(full, btr);
279:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_acquire);
280: 
281:     /* Step 1: Read data from linear part of buffer */
282:     tocopy = BUF_MIN(buff->size - r_ptr, btr);
283:     BUF_MEMCPY(d_ptr, &buff->buff[r_ptr], tocopy);
284:     d_ptr += tocopy;
285:     r_ptr += tocopy;
286:     btr -= tocopy;
287: 
288:     /* Step 2: Read data from beginning of buffer (overflow part) */
289:     if (btr > 0) {
290:         BUF_MEMCPY(d_ptr, buff->buff, btr);
291:         r_ptr = btr;
292:     }
293: 
294:     /* Step 3: Check end of buffer */
295:     if (r_ptr >= buff->size) {
296:         r_ptr = 0;
297:     }
298: 
299:     /*
300:      * Write final value to the actual running variable.
301:      * This is to ensure no write operation can access intermediate data
302:      */
303:     LWRB_STORE(buff->r_ptr, r_ptr, memory_order_release);
304: 
305:     BUF_SEND_EVT(buff, LWRB_EVT_READ, tocopy + btr);
306:     if (bread != NULL) {
307:         *bread = tocopy + btr;
308:     }
309:     return 1;
310: }
311: 
312: /**
313:  * \brief           Read from buffer without changing read pointer (peek only)
314:  * \param[in]       buff: Ring buffer instance
315:  * \param[in]       skip_count: Number of bytes to skip before reading data
316:  * \param[out]      data: Pointer to output memory to copy buffer data to
317:  * \param[in]       btp: Number of bytes to peek
318:  * \return          Number of bytes peeked and written to output array
319:  */
320: lwrb_sz_t
321: lwrb_peek(const lwrb_t* buff, lwrb_sz_t skip_count, void* data, lwrb_sz_t btp) {
322:     lwrb_sz_t full = 0, tocopy = 0, r_ptr = 0;
323:     uint8_t* d_ptr = data;
324: 
325:     if (!BUF_IS_VALID(buff) || data == NULL || btp == 0) {
326:         return 0;
327:     }
328: 
329:     /*
330:      * Calculate maximum number of bytes available to read
331:      * and check if we can even fit to it.
332:      * 
333:      * The skip count at size of buffer or above is invalid input,
334:      * thus we can safely exit the function call
335:      */
336:     full = lwrb_get_full(buff);
337:     if (skip_count >= full) {
338:         return 0;
339:     }
340:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
341:     r_ptr += skip_count;
342:     full -= skip_count;
343:     if (r_ptr >= buff->size) {
344:         r_ptr -= buff->size;
345:     }
346:     btp = BUF_MIN(full, btp);
347: 
348:     /* Step 1: Read data from linear part of the buffer */
349:     tocopy = BUF_MIN(buff->size - r_ptr, btp);
350:     BUF_MEMCPY(d_ptr, &buff->buff[r_ptr], tocopy);
351:     d_ptr += tocopy;
352:     btp -= tocopy;
353: 
354:     /* Step 2: Read data from the beginning of the buffer (overflow part) */
355:     if (btp > 0) {
356:         BUF_MEMCPY(d_ptr, buff->buff, btp);
357:     }
358:     return tocopy + btp;
359: }
360: 
361: /**
362:  * \brief           Get available size in buffer for write operation
363:  * \param[in]       buff: Ring buffer instance
364:  * \return          Number of free bytes in memory
365:  */
366: lwrb_sz_t
367: lwrb_get_free(const lwrb_t* buff) {
368:     lwrb_sz_t size = 0, w_ptr = 0, r_ptr = 0;
369: 
370:     if (!BUF_IS_VALID(buff)) {
371:         return 0;
372:     }
373: 
374:     /*
375:      * Copy buffer pointers to local variables with atomic access.
376:      *
377:      * To ensure thread safety (only when in single-entry, single-exit FIFO mode use case),
378:      * it is important to write buffer r and w values to local w and r variables.
379:      *
380:      * Local variables will ensure below if statements will always use the same value,
381:      * even if buff->w or buff->r get changed during interrupt processing.
382:      *
383:      * They may change during load operation, important is that
384:      * they do not change during if-else operations following these assignments.
385:      *
386:      * lwrb_get_free is only called for write purpose, and when in FIFO mode, then:
387:      * - buff->w pointer will not change by another process/interrupt because we are in write mode just now
388:      * - buff->r pointer may change by another process. If it gets changed after buff->r has been loaded to local variable,
389:      *    buffer will see "free size" less than it actually is. This is not a problem, application can
390:      *    always try again to write more data to remaining free memory that was read just during copy operation
391:      */
392:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
393:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
394: 
395:     if (w_ptr >= r_ptr) {
396:         size = buff->size - (w_ptr - r_ptr);
397:     } else {
398:         size = r_ptr - w_ptr;
399:     }
400: 
401:     /* Buffer free size is always 1 less than actual size */
402:     return size - 1;
403: }
404: 
405: /**
406:  * \brief           Get number of bytes currently available in buffer
407:  * \param[in]       buff: Ring buffer instance
408:  * \return          Number of bytes ready to be read
409:  */
410: lwrb_sz_t
411: lwrb_get_full(const lwrb_t* buff) {
412:     lwrb_sz_t size = 0, w_ptr = 0, r_ptr = 0;
413: 
414:     if (!BUF_IS_VALID(buff)) {
415:         return 0;
416:     }
417: 
418:     /*
419:      * Copy buffer pointers to local variables.
420:      *
421:      * To ensure thread safety (only when in single-entry, single-exit FIFO mode use case),
422:      * it is important to write buffer r and w values to local w and r variables.
423:      *
424:      * Local variables will ensure below if statements will always use the same value,
425:      * even if buff->w or buff->r get changed during interrupt processing.
426:      *
427:      * They may change during load operation, important is that
428:      * they do not change during if-else operations following these assignments.
429:      *
430:      * lwrb_get_full is only called for read purpose, and when in FIFO mode, then:
431:      * - buff->r pointer will not change by another process/interrupt because we are in read mode just now
432:      * - buff->w pointer may change by another process. If it gets changed after buff->w has been loaded to local variable,
433:      *    buffer will see "full size" less than it really is. This is not a problem, application can
434:      *    always try again to read more data from remaining full memory that was written just during copy operation
435:      */
436:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
437:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
438: 
439:     if (w_ptr >= r_ptr) {
440:         size = w_ptr - r_ptr;
441:     } else {
442:         size = buff->size - (r_ptr - w_ptr);
443:     }
444:     return size;
445: }
446: 
447: /**
448:  * \brief           Resets buffer to default values. Buffer size is not modified
449:  * \note            This function is not thread safe.
450:  *                      When used, application must ensure there is no active read/write operation
451:  * \param[in]       buff: Ring buffer instance
452:  */
453: void
454: lwrb_reset(lwrb_t* buff) {
455:     if (BUF_IS_VALID(buff)) {
456:         LWRB_STORE(buff->w_ptr, 0, memory_order_release);
457:         LWRB_STORE(buff->r_ptr, 0, memory_order_release);
458:         BUF_SEND_EVT(buff, LWRB_EVT_RESET, 0);
459:     }
460: }
461: 
462: /**
463:  * \brief           Get linear address for buffer for fast read
464:  * \param[in]       buff: Ring buffer instance
465:  * \return          Linear buffer start address
466:  */
467: void*
468: lwrb_get_linear_block_read_address(const lwrb_t* buff) {
469:     lwrb_sz_t ptr = 0;
470: 
471:     if (!BUF_IS_VALID(buff)) {
472:         return NULL;
473:     }
474:     ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
475:     return &buff->buff[ptr];
476: }
477: 
478: /**
479:  * \brief           Get length of linear block address before it overflows for read operation
480:  * \param[in]       buff: Ring buffer instance
481:  * \return          Linear buffer size in units of bytes for read operation
482:  */
483: lwrb_sz_t
484: lwrb_get_linear_block_read_length(const lwrb_t* buff) {
485:     lwrb_sz_t len = 0, w_ptr = 0, r_ptr = 0;
486: 
487:     if (!BUF_IS_VALID(buff)) {
488:         return 0;
489:     }
490: 
491:     /*
492:      * Use temporary values in case they are changed during operations.
493:      * See lwrb_buff_free or lwrb_buff_full functions for more information why this is OK.
494:      */
495:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
496:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
497: 
498:     if (w_ptr > r_ptr) {
499:         len = w_ptr - r_ptr;
500:     } else if (r_ptr > w_ptr) {
501:         len = buff->size - r_ptr;
502:     } else {
503:         len = 0;
504:     }
505:     return len;
506: }
507: 
508: /**
509:  * \brief           Skip (ignore; advance read pointer) buffer data
510:  * Marks data as read in the buffer and increases free memory for up to `len` bytes
511:  *
512:  * \note            Useful at the end of streaming transfer such as DMA
513:  * \param[in]       buff: Ring buffer instance
514:  * \param[in]       len: Number of bytes to skip and mark as read
515:  * \return          Number of bytes skipped
516:  */
517: lwrb_sz_t
518: lwrb_skip(lwrb_t* buff, lwrb_sz_t len) {
519:     lwrb_sz_t full = 0, r_ptr = 0;
520: 
521:     if (!BUF_IS_VALID(buff) || len == 0) {
522:         return 0;
523:     }
524: 
525:     full = lwrb_get_full(buff);
526:     len = BUF_MIN(len, full);
527:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_acquire);
528:     r_ptr += len;
529:     if (r_ptr >= buff->size) {
530:         r_ptr -= buff->size;
531:     }
532:     LWRB_STORE(buff->r_ptr, r_ptr, memory_order_release);
533:     BUF_SEND_EVT(buff, LWRB_EVT_READ, len);
534:     return len;
535: }
536: 
537: /**
538:  * \brief           Get linear address for buffer for fast write
539:  * \param[in]       buff: Ring buffer instance
540:  * \return          Linear buffer start address
541:  */
542: void*
543: lwrb_get_linear_block_write_address(const lwrb_t* buff) {
544:     lwrb_sz_t ptr = 0;
545: 
546:     if (!BUF_IS_VALID(buff)) {
547:         return NULL;
548:     }
549:     ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
550:     return &buff->buff[ptr];
551: }
552: 
553: /**
554:  * \brief           Get length of linear block address before it overflows for write operation
555:  * \param[in]       buff: Ring buffer instance
556:  * \return          Linear buffer size in units of bytes for write operation
557:  */
558: lwrb_sz_t
559: lwrb_get_linear_block_write_length(const lwrb_t* buff) {
560:     lwrb_sz_t len = 0, w_ptr = 0, r_ptr = 0;
561: 
562:     if (!BUF_IS_VALID(buff)) {
563:         return 0;
564:     }
565: 
566:     /*
567:      * Use temporary values in case they are changed during operations.
568:      * See lwrb_buff_free or lwrb_buff_full functions for more information why this is OK.
569:      */
570:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
571:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
572: 
573:     if (w_ptr >= r_ptr) {
574:         len = buff->size - w_ptr;
575:         /*
576:          * When read pointer is 0,
577:          * maximal length is one less as if too many bytes
578:          * are written, buffer would be considered empty again (r == w)
579:          */
580:         if (r_ptr == 0) {
581:             /*
582:              * Cannot overflow:
583:              * - If r is not 0, statement does not get called
584:              * - buff->size cannot be 0 and if r is 0, len is greater 0
585:              */
586:             --len;
587:         }
588:     } else {
589:         len = r_ptr - w_ptr - 1;
590:     }
591:     return len;
592: }
593: 
594: /**
595:  * \brief           Advance write pointer in the buffer.
596:  * Similar to skip function but modifies write pointer instead of read
597:  *
598:  * \note            Useful when hardware is writing to buffer and application needs to increase number
599:  *                      of bytes written to buffer by hardware
600:  * \param[in]       buff: Ring buffer instance
601:  * \param[in]       len: Number of bytes to advance
602:  * \return          Number of bytes advanced for write operation
603:  */
604: lwrb_sz_t
605: lwrb_advance(lwrb_t* buff, lwrb_sz_t len) {
606:     lwrb_sz_t free = 0, w_ptr = 0;
607: 
608:     if (!BUF_IS_VALID(buff) || len == 0) {
609:         return 0;
610:     }
611: 
612:     /* Use local variables before writing back to main structure */
613:     free = lwrb_get_free(buff);
614:     len = BUF_MIN(len, free);
615:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_acquire);
616:     w_ptr += len;
617:     if (w_ptr >= buff->size) {
618:         w_ptr -= buff->size;
619:     }
620:     LWRB_STORE(buff->w_ptr, w_ptr, memory_order_release);
621:     BUF_SEND_EVT(buff, LWRB_EVT_WRITE, len);
622:     return len;
623: }
624: 
625: /**
626:  * \brief           Searches for a *needle* in an array, starting from given offset.
627:  * 
628:  * \note            This function is not thread-safe. 
629:  * 
630:  * \param           buff: Ring buffer to search for needle in
631:  * \param           bts: Constant byte array sequence to search for in a buffer
632:  * \param           len: Length of the \arg bts array 
633:  * \param           start_offset: Start offset in the buffer
634:  * \param           found_idx: Pointer to variable to write index in array where bts has been found
635:  *                      Must not be set to `NULL`
636:  * \return          `1` if \arg bts found, `0` otherwise
637:  */
638: uint8_t
639: lwrb_find(const lwrb_t* buff, const void* bts, lwrb_sz_t len, lwrb_sz_t start_offset, lwrb_sz_t* found_idx) {
640:     lwrb_sz_t full = 0, r_ptr = 0, buff_r_ptr = 0, max_x = 0;
641:     uint8_t found = 0;
642:     const uint8_t* needle = bts;
643: 
644:     if (!BUF_IS_VALID(buff) || needle == NULL || len == 0 || found_idx == NULL) {
645:         return 0;
646:     }
647:     *found_idx = 0;
648: 
649:     full = lwrb_get_full(buff);
650:     /* Verify initial conditions */
651:     if (full < (len + start_offset)) {
652:         return 0;
653:     }
654: 
655:     /* Get actual buffer read pointer for this search */
656:     buff_r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
657: 
658:     /* Max number of for loops is buff_full - input_len - start_offset of buffer length */
659:     max_x = full - len;
660:     for (lwrb_sz_t skip_x = start_offset; !found && skip_x <= max_x; ++skip_x) {
661:         found = 1; /* Found by default */
662: 
663:         /* Prepare the starting point for reading */
664:         r_ptr = buff_r_ptr + skip_x;
665:         if (r_ptr >= buff->size) {
666:             r_ptr -= buff->size;
667:         }
668: 
669:         /* Search in the buffer */
670:         for (lwrb_sz_t idx = 0; idx < len; ++idx) {
671:             if (buff->buff[r_ptr] != needle[idx]) {
672:                 found = 0;
673:                 break;
674:             }
675:             if (++r_ptr >= buff->size) {
676:                 r_ptr = 0;
677:             }
678:         }
679:         if (found) {
680:             *found_idx = skip_x;
681:         }
682:     }
683:     return found;
684: }

