180	lwrb_write_ex(lwrb_t* buff, const void* data, lwrb_sz_t btw, lwrb_sz_t* bwritten, uint16_t flags) {
181	    lwrb_sz_t tocopy = 0, free = 0, w_ptr = 0;
182	    const uint8_t* d_ptr = data;
183	
184	    if (!BUF_IS_VALID(buff) || data == NULL || btw == 0) {
185	        return 0;
186	    }
187	
188	    /* Calculate maximum number of bytes available to write */
189	    free = lwrb_get_free(buff);
190	    /* If no memory, or if user wants to write ALL data but no enough space, exit early */
191	    if (free == 0 || (free < btw && (flags & LWRB_FLAG_WRITE_ALL))) {
192	        return 0;
193	    }
194	    btw = BUF_MIN(free, btw);
195	    w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_acquire);
196	
197	    /* Step 1: Write data to linear part of buffer */
198	    tocopy = BUF_MIN(buff->size - w_ptr, btw);
199	    BUF_MEMCPY(&buff->buff[w_ptr], d_ptr, tocopy);
200	    d_ptr += tocopy;
201	    w_ptr += tocopy;
202	    btw -= tocopy;
203	
204	    /* Step 2: Write data to beginning of buffer (overflow part) */
205	    if (btw > 0) {
206	        BUF_MEMCPY(buff->buff, d_ptr, btw);
207	        w_ptr = btw;
208	    }
209	
210	    /* Step 3: Check end of buffer */
211	    if (w_ptr >= buff->size) {
212	        w_ptr = 0;
213	    }
214	
215	    /*
216	     * Write final value to the actual running variable.
217	     * This is to ensure no read operation can access intermediate data
218	     */
219	    LWRB_STORE(buff->w_ptr, w_ptr, memory_order_release);
220	
221	    BUF_SEND_EVT(buff, LWRB_EVT_WRITE, tocopy + btw);
222	    if (bwritten != NULL) {
223	        *bwritten = tocopy + btw;
224	    }
225	    return 1;
226	}
